package dao;
import database.DBConnection; import model.*; import org.springframework.stereotype.Repository; import java.sql.*; import java.util.*;
@Repository public class CartDAO {
 public int createCart(String name){try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement("INSERT INTO Cart(customer_name) VALUES(?)",Statement.RETURN_GENERATED_KEYS)){p.setString(1,name);p.executeUpdate();try(ResultSet r=p.getGeneratedKeys()){if(r.next())return r.getInt(1);}}catch(Exception e){e.printStackTrace();}return 0;}
 public boolean addToCart(int cartId,int foodId){String q="SELECT quantity FROM Cart_Items WHERE cart_id=? AND food_id=?";try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement(q)){p.setInt(1,cartId);p.setInt(2,foodId);try(ResultSet r=p.executeQuery()){String sql=r.next()?"UPDATE Cart_Items SET quantity=quantity+1 WHERE cart_id=? AND food_id=?":"INSERT INTO Cart_Items(cart_id,food_id,quantity) VALUES(?,?,1)";try(PreparedStatement x=c.prepareStatement(sql)){x.setInt(1,cartId);x.setInt(2,foodId);return x.executeUpdate()>0;}}}catch(Exception e){e.printStackTrace();}return false;}
 public List<CartItem> getCartItems(int id){List<CartItem> l=new ArrayList<>();String s="SELECT ci.cart_item_id,ci.cart_id,ci.food_id,ci.quantity,f.food_name,f.category,f.price,f.climate,f.availability,f.description FROM Cart_Items ci JOIN Food f ON ci.food_id=f.food_id WHERE ci.cart_id=?";try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement(s)){p.setInt(1,id);try(ResultSet r=p.executeQuery()){while(r.next()){CartItem i=new CartItem();i.setCartItemId(r.getInt("cart_item_id"));i.setCartId(r.getInt("cart_id"));i.setFoodId(r.getInt("food_id"));i.setQuantity(r.getInt("quantity"));Food f=new Food();f.setFoodId(r.getInt("food_id"));f.setFoodName(r.getString("food_name"));f.setCategory(r.getString("category"));f.setPrice(r.getDouble("price"));f.setClimate(r.getString("climate"));f.setAvailability(r.getString("availability"));f.setDescription(r.getString("description"));i.setFood(f);l.add(i);}}}catch(Exception e){e.printStackTrace();}return l;}
 private boolean update(String s,int id){try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement(s)){p.setInt(1,id);return p.executeUpdate()>0;}catch(Exception e){e.printStackTrace();return false;}}
 public boolean increaseQuantity(int id){return update("UPDATE Cart_Items SET quantity=quantity+1 WHERE cart_item_id=?",id);} public boolean decreaseQuantity(int id){return update("UPDATE Cart_Items SET quantity=quantity-1 WHERE cart_item_id=? AND quantity>1",id);} public boolean removeItem(int id){return update("DELETE FROM Cart_Items WHERE cart_item_id=?",id);}
 public int getCartCount(int id){try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement("SELECT COALESCE(SUM(quantity),0) FROM Cart_Items WHERE cart_id=?")){p.setInt(1,id);try(ResultSet r=p.executeQuery()){r.next();return r.getInt(1);}}catch(Exception e){return 0;}}
 public double getCartTotal(int id){try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement("SELECT COALESCE(SUM(ci.quantity*f.price),0) FROM Cart_Items ci JOIN Food f ON ci.food_id=f.food_id WHERE ci.cart_id=?")){p.setInt(1,id);try(ResultSet r=p.executeQuery()){r.next();return r.getDouble(1);}}catch(Exception e){return 0;}}
}
